// === Tab: mySketch ===
/************************
 * VOID
 * by twitter.com/mattywillo_
 * made for twitter.com/sableRaph's #WCCChallenge topic: void
 * jump on the birbs nest discord to join the challenge and to vote on future topics:
 * discord.gg/S8c7qcjw2b
 ************************/
//runs weirdly slow on firefox for me, best run on chrome

let {PI, sin, cos, random, sqrt, pow, hypot, min, max, abs} = Math;

//state variables
let res, lineSh, effSh, lineGr, effGr;
let t = 0;

//config variables
let step = 0.0001;      //step per frame
let line_count = 400;   //line count. lower for performance
let seg_count = 30;     //segments per line. lower for performance
let mstep = 10;         //how many times to sample the field function per line segment. increasing makes longer, but more same-y lines
let fstep = 0.001;      //distance factor for each sample of the field. increasing yields similar results to increasing mstep
let void_count = 15;    //how many void spots
let warp_count = 10;    //how many warp spots
let aberration_f = 200; //strength of the chromatic aberration effect

//each property is a knob to configure the field function, each array entry is a possible value for that knob
//the first loop always uses the first value of each array, each subsequent loop choses a random value from each array
//this lets the first loop be semi-predictable every time
let fcp = {
  a: [8,4,2,10],
  b: [4,6,8,3],
  c: [4,5,6,7],
  d: [6,2,3],
  e: [.5, .25, .75, 1, 0],
  f: [0.2, 0, .5, .8, 1, 2],
  g: [.05, .02, .075],
}

//i love clean and readable code. i'd love to write some one day.

//gen_fc generates a random set of properties from the fcp arrays above
let gen_fc = ()=>Object.fromEntries(Object.entries(fcp).map(([k,v])=>[k,v[random()*v.length|0]]))
//fc is the actual configuration, on the first loop we just take the first value of each array
let fc = Object.fromEntries(Object.entries(fcp).map(([k,v])=>[k,v[0]]))

//field function, takes a point [x y] and returns a moved point [x y], behaviour controlled by fstep and fc
let field = (p)=>{
  return [...Array(mstep)].reduce(([x,y])=>{
    let a = sin(y*fc.a*PI+x*fc.b*PI);
    let b = (sin(y*fc.c*x*fc.d*PI)*.5+.5)*PI*fc.e;
    return [x+a*fstep, y-b*fstep];
  }, p);
}

//generate points for each line/shape
let gen_points = ()=>[...Array(line_count)]                                                //make line_count shapes, for each one:
    .map((_,i)=>[random()*2-1, random()*2-1, 0])                                           //generate a random origin point in range [-1:1,-1:1,0]
    .map(([x,y,z])=>[[x,y,z], [x+random()*fc.g-(fc.g*.5), y+random()*fc.g-(fc.g*.5), z]])  //generate a compliment point near the origin point
    .map((o,j)=>[...Array(seg_count)].reduce((acc,_,k)=>{                                  //generate an array for seg_count point pairs
      let p = k>0?acc[k-1]:o;                                                              //start with the previous point pair, or the origin and compliment
      let z = -k/seg_count*fc.f;                                                           //move away from the camera in the z direction each segment
      return [...acc, [[...field(p[0]), z], [...field(p[1]), z]]]},[]))                    //move the point pair along the field and add it to the shape
    .map((x,i)=>i%2==0?x:x.reverse());                                                     //reverse the order of every other line/shape so half of them animate backwards

//generate some starting points
let points = gen_points();

//gen_voids/gen_warps, generates new voids and warp points, and some useful random values for each point
//also make the first void larger than the rest so we get one big spot and a bunch of small ones
let gen_voids = ()=>[...Array(void_count)].map((_,i)=>[random()*2-1,random()*2-1,random()*.1+(i==0?.9:.1),random()]);
let gen_warps = ()=>[...Array(warp_count)].map(()=>[random()*2-1,random()*2-1,random(),random()*5|0]);
let voids = gen_voids();
let warps = gen_warps();

function draw() {
  //generate new settings, points, voids and warps if we're going to start a new loop this frame
  if(((t*.5|0)%2) != (((t+step*deltaTime)*.5|0)%2)) {
    fc = gen_fc();
    points = gen_points();
    voids = gen_voids();
    warps = gen_warps();
  }
  t += step*deltaTime;

  //draw the shapes/lines
  //the fade in animation is done in a shader
  //everything is drawn to a p5 graphic thats passed to the distortion shader
  //don't bother redrawing the shapes in p5 if we're in the warp/void part of the loop
  if((t|0)%2==0) {
    lineGr.noStroke();
    lineGr.background((t*.5|0)%2?0.1:.95);
    lineSh.setUniform("t", t%1);
    lineSh.setUniform("l", t|0);
    lineGr.shader(lineSh);
    points.forEach((e,i)=>{
      lineGr.beginShape(TRIANGLE_STRIP);
      e.forEach((f,j)=>f.forEach((p,k)=>{
        lineGr.fill(i/line_count, j/seg_count, k) //set the colour of each vertex to be [current line, current segment, current side of line], so we can pick colours in shader
        lineGr.vertex(...p)
      }));
      lineGr.endShape();
    });
  }

  //the distortion/output shader
  effSh.setUniform("t", t%1);
  effSh.setUniform("l", t|0);
  effSh.setUniform("voids", voids.flat());
  effSh.setUniform("warps", warps.flat());
  effSh.setUniform("tex", lineGr);
  effSh.setUniform("last", effGr);
  effSh.setUniform("af", aberration_f);
  effGr.shader(effSh);
  effGr.rect(0,0,0);

  image(effGr, -res*.7, -res*.5);
}

//without noprotect openprocessing tries to inject loop protection into the glsl code which lmao very funny
// noprotect

//line shader, handles the colouring and 'drawing' animation of the lines
const lineSrc = [`
attribute vec3 aPosition;
attribute vec4 aVertexColor;
uniform mat4 uModelViewMatrix;
uniform mat4 uProjectionMatrix;
varying vec4 vColor;
void main() {
  //vertex shader pretty much does nothing, just a subset of default p5 behaviour
  gl_Position = uProjectionMatrix * uModelViewMatrix * vec4(aPosition, 1.);
  vColor = aVertexColor;
}
`,`
precision highp float;
#define PI `+PI+`
varying vec4 vColor;
uniform float t,l;
void main() {
  //do the 'drawing' animation by discarding fragments further along each line that the current timestep
  if(mod(l,2.)==0. && vColor.y > smoothstep(0.+vColor.x*.5,.7,smoothstep(0.,1.,t)-vColor.x*.3)) discard;
  //generate different colours for each line, switching palettes if the current loop is black or white background
  gl_FragColor = mod(l*.5,2.)==0.
    ? vec4(sin(vColor.x*8.*PI)*.5+.5, sin(vColor.y*vColor.x*2.*PI)*.5+.5, vColor.z*sin(vColor.y*4.)*.5+.5, 1.)
    : vec4(sin(vColor.x*8.*PI)*.5+.5, vColor.y*sin(vColor.x*4.*PI)*.5+.5, vColor.z*sin(vColor.y*2.)*.5+.5, 1.);
}
`];

//effect shader, does the voids and warping
const effSrc = [`
attribute vec3 aPosition;
varying vec2 uv;
void main() {
  //make the quad full screen and send uv to the frag shader
  gl_Position = vec4(aPosition*2.-1., 1.0);
  uv = aPosition.xy;
  uv.y = 1.-uv.y;
}
`,`
precision highp float;
#define PI `+PI+`
#define VOIDS `+void_count+`
#define WARPS `+warp_count+`
varying vec2 uv;
uniform float t,l,af;
uniform vec4 voids[VOIDS];
uniform vec4 warps[WARPS];
uniform sampler2D tex, last;

//2d rotate
mat2 rot(float a) {
  return mat2(cos(a), -sin(a), sin(a), cos(a));
}

//lazy noise implementation
float noise(vec2 p ) {
	return sin(p.x*.5*fract(sin(dot(p,vec2(95.25985,7575.24255)))))*sin(p.y*.5*fract(sin(dot(p,vec2(136.2482257,148.113198)))));
}

//lazy implentation of fbm/domain warping as per iq
float fbm (vec2 p) {
    float v = 0.0;
    for (int i = 0; i < 10; ++i) v += pow(.5,float(i+1)) * noise(p*=rot(.5+noise(p)));
    return v;
}

void main() {
  //our eventual output colour
  vec3 c = vec3(0.5);
  if(mod(l,2.)==0.) {
    //if we're on the first half of the loop, just draw the input texture
    c = vec3(texture2D(tex, uv));
  } else {
    //otherwise lets mess with the previous frame
    vec2 auv = uv*2.-1.;  //our altered uv coordinates
    vec2 p = auv;         //our original coordinates
    float d = 0.;

    for(int i = 0; i < VOIDS; i++) {
      //push the pixels around each void outward
      d = length(p-voids[i].xy)-smoothstep(.0, .5, t)*voids[i].z*mix(.5,4.,smoothstep(.8,1.,t)) + (sin(p.x*20.)*sin(p.y*20.)*.1)*t;
      if(d<0.) auv += 0.021 * normalize(p-voids[i].xy) * d;
      //add a dash of black/white to each void
      d = length(p-voids[i].xy)-smoothstep(.1, .5, t)*mix(.001,2.,smoothstep(.9,1.,t)) + sin(p.x*20.)*sin(p.y*20.)*.1*smoothstep(.9,1.,t);
      if(d<0.) c = vec3((mod(floor(l*.5),2.)==0.)?0.1:.95);
    }

    for(int i = 0; i < WARPS; i++) {
      vec2 q = p-warps[i].xy;
      d = length(q)-smoothstep(.0, 1., t)*(.8+.2*warps[i].z) + sin(auv.x*30.)*sin(auv.y*30.)*.1;
      if(d<0.) {
        //4th component of each warp uniform has a random id corresponding to a warp mode below
        float wid = warps[i].w;
        if(wid == 0.) {
          float a = fbm(q*20.)*PI*2.;
          auv += vec2(cos(a), sin(a))*.001;
        } else if(wid == 1.) {
          auv.x += sin(q.y*4.*PI)*sin(q.x*16.*PI)*fbm(q);
          auv.y += sin(q.y*4.*PI)*sin(q.x*16.*PI)*fbm(q*.5);
        } else if(wid == 2.) {
          float a = atan(q.y*2.*PI,q.x*4.) + PI * 0.5;
          auv += vec2(cos(a), sin(a))*fbm(q)*d;
        } else if(wid == 3.) {
          auv *= rot(q.y*PI*d*fbm(q)*.1);
        } else if(wid == 4.) {
          auv -= normalize(q)*d*.005;
        }
      }
    }

    //apply chromatic aberration based on the difference between the original uv coord and the modified coord
    float diff = length(p-auv)*af;
    //if c.x != .5 then we added colour for a void, and we should let that replace the colour from the previous frame
    if(c.x==.5) c = vec3(texture2D(last, auv*.5+.5+vec2(.001,0)*diff).r, texture2D(last, auv*.5+.5).g, texture2D(last, auv*.5+.5-vec2(.001,0)*diff).b);
  }
  gl_FragColor = vec4(c,1);
}`];

function setup() {
  res = Math.min(1112, 834);
	createCanvas(1112, 834, WEBGL);
  colorMode(RGB, 1, 1, 1, 1);
  setAttributes('antialias', true);


  lineSh = new p5.Shader(undefined, ...lineSrc);
  lineGr = createGraphics(width*1.2, height, WEBGL);
  lineGr.setAttributes('antialias', true);
  lineGr.perspective();
  lineGr.colorMode(RGB, 1, 1, 1, 1);
  lineGr.scale(res, res, res);

  //the king solomon solution to z fighting: just turn off depth testing
  lineGr._renderer.GL.disable(lineGr._renderer.GL.DEPTH_TEST);

  effSh = new p5.Shader(undefined, ...effSrc);
  effGr = createGraphics(width*1.2, height, WEBGL);
}

function windowResized() {
  res = min(1112, 834);
  resizeCanvas(res, res);
}

// save jpg
let lapse = 0;    // mouse timer
function mousePressed(){
  // prevents mouse press from registering twice
  if (millis() - lapse > 400){
  save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
    lapse = millis();
  }
}

